def pending_jobs(jobs):
    for job in jobs:
        if job['status'] == 'pending':
            yield job


def describe_jobs(jobs):
    for job in jobs:
        yield f"{job['id']}: {job['name']}"


def pending_job_descriptions(jobs):
    return describe_jobs(pending_jobs(jobs))
